  const progress={unlocked:+localStorage.getItem('jellyUnlocked')||0,total:+localStorage.getItem('jellyTreats')||0};let levelIndex=0,game=null;
  class AudioBox{constructor(){this.a=null}init(){if(!this.a)this.a=new(AudioContext||webkitAudioContext)()}tone(f,d=.12,type='sine',v=.05,slide=0){if(muted)return;this.init();const t=this.a.currentTime,o=this.a.createOscillator(),g=this.a.createGain();o.type=type;o.frequency.setValueAtTime(f,t);if(slide)o.frequency.exponentialRampToValueAtTime(Math.max(40,f+slide),t+d);g.gain.setValueAtTime(v,t);g.gain.exponentialRampToValueAtTime(.001,t+d);o.connect(g).connect(this.a.destination);o.start();o.stop(t+d)}jump(){this.tone(360,.13,'sine',.065,240)}collect(){this.tone(620,.08,'triangle',.06,260);setTimeout(()=>this.tone(930,.12,'triangle',.045),65)}bark(){this.tone(205,.08,'square',.04,-55);setTimeout(()=>this.tone(295,.09,'square',.035,-75),75)}hurt(){this.tone(180,.22,'sawtooth',.03,-95)}spring(){this.tone(220,.18,'sine',.06,560)}win(){[523,659,784,1047].forEach((n,i)=>setTimeout(()=>this.tone(n,.2,'triangle',.055),i*115))}trumpet(){this.tone(390,.12,'sawtooth',.018,80);setTimeout(()=>this.tone(520,.14,'sawtooth',.014),90)}}const audio=new AudioBox();
  function makeLevel(i){const src=JELLY_LEVELS[i],plats=src.platforms.map(a=>({x:a[0],y:a[1],w:a[2],h:a[3]})),moving=src.moving.map((a,n)=>({x:a[0],y:a[1],w:a[2],h:a[3],axis:a[4],range:a[5],speed:a[6],phase:a[7],baseX:a[0],baseY:a[1],lastX:a[0],lastY:a[1],kind:n%3}));const topAt=x=>{const p=plats.find(q=>x>q.x&&x<q.x+q.w);return p?p.y:410};return{...src,platforms:plats,moving,treats:src.treats.map(a=>({x:a[0],y:a[1],taken:false,spin:Math.random()*6})),enemies:src.enemies.map((a,n)=>({x:a[0],y:topAt(a[0])-55,homeX:a[0],homeY:topAt(a[0])-55,kind:a[2],dir:n%2?1:-1,state:'move',timer:Math.random()*1.8,cooldown:1+Math.random()*2,stun:0,frame:0,vy:0})),goal:{x:src.goal[0],y:src.goal[1],w:92,h:105},particles:[],barks:[],waves:[],camera:0,time:0,weather:[]}}
  function newGame(i=levelIndex){levelIndex=i;game=makeLevel(i);const world=Math.floor(i/3);game.player={x:70,y:350,vx:0,vy:0,w:72,h:56,on:false,platform:null,dir:1,hearts:3,treats:0,inv:0,barkCd:0,anim:0};running=true;paused=false;completing=false;hideAll();ui.hud.hidden=false;ui.pauseBtn.hidden=false;ui.touch.hidden=false;updateHud();canvas.focus();setTimeout(()=>toast(game.tip),300)}
