  function updateHud(){const d=worlds[Math.floor(levelIndex/3)],l=JELLY_LEVELS[levelIndex];ui.city.textContent=d.city;ui.level.textContent=`${levelIndex%3+1} · ${l.name}`;ui.treats.textContent=game?.player.treats||0;const h=game?.player.hearts||0;ui.hearts.textContent='♥'.repeat(h)+'♡'.repeat(3-h)}
