    const accel=p.on?1580:900;if(keys.left){p.vx=Math.max(-285,p.vx-accel*dt);p.dir=-1}if(keys.right){p.vx=Math.min(285,p.vx+accel*dt);p.dir=1}if(!keys.left&&!keys.right)p.vx*=Math.pow(.002,dt);p.vy+=G*dt;p.x=Math.max(0,Math.min(L.width-p.w,p.x+p.vx*dt));const oldBottom=p.y+p.h;p.y+=p.vy*dt;p.on=false;p.platform=null;
