  function damage(fell){const p=game.player;p.hearts--;p.inv=2;shake=8;audio.hurt();updateHud();if(p.hearts<=0){running=false;toast('Jelly catches her breath — you can do it!');setTimeout(()=>newGame(levelIndex),800)}else{p.x=Math.max(55,p.x-145);p.y=260;p.vx=0;p.vy=0;toast(fell?'A friendly cloud carried Jelly back!':'Oops! One courage heart used.')}}
