  function draw(){ctx.clearRect(0,0,W,H);if(!game){idleSky();return}ctx.save();if(shake)ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);drawSky();drawBackdrop();drawPlatforms();drawCollectibles();drawEnemies();drawPlayer();drawFX();ctx.restore()}
  function idleSky(){const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#76dcf3');g.addColorStop(1,'#ffe0a5');ctx.fillStyle=g;ctx.fillRect(0,0,W,H)}
